use std::fs

fn is_int(t: string) -> bool {
    let cs: Vec<char> = t.chars().collect()
    let n: int = cs.len() as int
    if n == 0 { return false }
    let mut start = 0
    if cs[0] == '-' { start = 1 }
    if start >= n { return false }
    let mut i = start
    while i < n {
        if cs[i] < '0' || cs[i] > '9' { return false }
        i += 1
    }
    true
}

fn to_int(t: string) -> int {
    let cs: Vec<char> = t.chars().collect()
    let n: int = cs.len() as int
    let mut neg = false
    let mut i = 0
    if cs[0] == '-' {
        neg = true
        i = 1
    }
    let mut v: int = 0
    while i < n {
        v = v * 10 + (cs[i] as int - '0' as int)
        i += 1
    }
    if neg { -v } else { v }
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = Vec::new()
    for t in line.split(" ") {
        if t == "" { continue }
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 { return "error: underflow" }
            let b = st.pop() ?? 0
            let a = st.pop() ?? 0
            if t == "+" { st.push(a + b) }
            else if t == "-" { st.push(a - b) }
            else if t == "*" { st.push(a * b) }
            else {
                if b == 0 { return "error: divzero" }
                st.push(a / b)
            }
            continue
        }
        if !is_int(t) { return "error: token" }
        st.push(to_int(t))
    }
    if st.len() != 1 { return "error: leftover" }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" { continue }
        println(eval(line.trim()))
    }
}

